import React, { useEffect, useState } from 'react';
import { BookOpen, Database, FileText, Upload, Download, Plus, Search, X, ShieldCheck, History, AlertCircle, CheckCircle2, ExternalLink, Layers, SlidersHorizontal, ArrowUpRight } from 'lucide-react';
import './reference-pages.css';

const today = () => new Date().toISOString().slice(0, 10);
const uid = (prefix) => `${prefix}-${Date.now().toString(36).toUpperCase()}`;
function useSaved(key, initial) {
  const [value, setValue] = useState(() => { try { return JSON.parse(localStorage.getItem(key)) || initial; } catch { return initial; } });
  useEffect(() => { localStorage.setItem(key, JSON.stringify(value)); }, [key, value]);
  return [value, setValue];
}
function Tag({ children }) {
  const type = ['已发布', '有效', '已验收', '已接受', '量产'].includes(children) ? 'success' : ['已撤销', '已过期', '已停用', '退回', '被替代'].includes(children) ? 'danger' : ['待审核', '待核对', '候选', '部分接受'].includes(children) ? 'warning' : 'neutral';
  return <span className={`badge ${type}`}>{children}</span>;
}
function Dialog({ title, children, footer, onClose, drawer = false, wide = false }) {
  useEffect(() => { const close = (e) => e.key === 'Escape' && onClose(); window.addEventListener('keydown', close); return () => window.removeEventListener('keydown', close); }, [onClose]);
  return <div className={`ref-overlay ${drawer ? 'ref-drawer-overlay' : ''}`} onMouseDown={(e) => e.target === e.currentTarget && onClose()}><section role="dialog" aria-modal="true" aria-label={title} className={`${drawer ? 'ref-drawer' : 'ref-modal'} ${wide ? 'ref-wide' : ''}`}><header className="ref-modal-head"><div><span className="ref-eyebrow">FEP 工作空间</span><h2>{title}</h2></div><button className="ref-icon-button" aria-label="关闭" onClick={onClose}><X size={20}/></button></header><div className="ref-modal-content">{children}</div>{footer && <footer className="ref-modal-footer">{footer}</footer>}</section></div>;
}
function Field({ label, children, required, full }) { return <label className={`field ${full ? 'ref-full' : ''}`}><span>{label}{required && <b className="ref-required"> *</b>}</span>{children}</label>; }
function Input({ value, onChange, ...props }) { return <input className="input" value={value || ''} onChange={(e) => onChange(e.target.value)} {...props}/>; }
function Area({ value, onChange, ...props }) { return <textarea className="input ref-textarea" value={value || ''} onChange={(e) => onChange(e.target.value)} {...props}/>; }
function Select({ value, onChange, options, label }) { return <select aria-label={label} className="select" value={value} onChange={(e) => onChange(e.target.value)}>{options.map((item) => <option key={typeof item === 'string' ? item : item.value} value={typeof item === 'string' ? item : item.value}>{typeof item === 'string' ? item : item.label}</option>)}</select>; }
function Notice({ children, warning = false }) { return <div className={`ref-notice ${warning ? 'ref-notice-warning' : ''}`}><AlertCircle size={16}/><div>{children}</div></div>; }
function Empty({ children = '没有符合筛选条件的记录' }) { return <div className="empty-state ref-empty"><Search size={30}/><strong>{children}</strong><p>尝试调整关键词或筛选条件。</p></div>; }
function Paginator({ total, page, setPage, pageSize, setPageSize }) { const pages = Math.max(1,Math.ceil(total/pageSize)); const currentPage = Math.min(page,pages); return <div className="ref-pagination"><span>显示 {total ? (currentPage-1)*pageSize+1 : 0}–{Math.min(currentPage*pageSize,total)} 条，共 {total} 条</span><div><Select label="每页条数" value={String(pageSize)} onChange={(v) => {setPageSize(Number(v));setPage(1);}} options={[{value:'5',label:'5 条 / 页'},{value:'10',label:'10 条 / 页'},{value:'20',label:'20 条 / 页'}]}/><button className="btn btn-sm" disabled={currentPage === 1} onClick={() => setPage(currentPage-1)}>‹</button><button className="btn btn-sm ref-page-number" disabled>{currentPage}</button><button className="btn btn-sm" disabled={currentPage === pages} onClick={() => setPage(currentPage+1)}>›</button></div></div>; }
function KeyValues({ entries }) { return <dl className="ref-kv">{entries.map(([key, value]) => <div key={key}><dt>{key}</dt><dd>{value || '—'}</dd></div>)}</dl>; }
function csvDownload(name, rows) { const a = document.createElement('a'); const url = URL.createObjectURL(new Blob(['\uFEFF' + rows.map((row) => row.map((cell) => `"${String(cell).replaceAll('"', '""')}"`).join(',')).join('\r\n')], {type:'text/csv;charset=utf-8;'})); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 500); }
function Heading({ eyebrow, title, description, actions }) { return <div className="page-heading"><div><div className="ref-eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div><div className="page-actions">{actions}</div></div>; }
function ReviewDialog({ item, action, onClose, onConfirm, impact = 0 }) {
  const [reason, setReason] = useState(''); const [error, setError] = useState('');
  const needReason = ['退回', '撤销', '停用', '替代'].includes(action);
  return <Dialog title={`${action}${item.id ? ` · ${item.id}` : ''}`} onClose={onClose} footer={<><button className="btn" onClick={onClose}>取消</button><button className={`btn ${['撤销', '停用', '退回'].includes(action) ? 'btn-danger' : 'btn-primary'}`} onClick={() => { if (needReason && !reason.trim()) return setError('请填写操作原因。'); onConfirm(reason); }}>{action === '批准发布' ? '确认批准并发布' : `确认${action}`}</button></>}><KeyValues entries={[["对象版本", `${item.title || item.name || item.metric} · v${item.version || 1}`], ['当前状态', item.status], ['适用范围', item.conditions || item.scope || item.config || 'FEP 授权项目']]}/><Notice warning={impact > 0}>{impact > 0 ? `本次变更影响 ${impact} 个可访问引用；将标记为待复核并保留原版本。` : '操作将保留版本和审核记录。只有已发布、有效且范围匹配的资料可作为应答依据。'}</Notice><Field label={needReason ? '操作原因' : '审核意见'} required={needReason}><Area value={reason} onChange={setReason} placeholder={needReason ? '说明原因及需要注意的影响…' : '填写适用范围、证据核对结果…'}/></Field>{error && <p className="ref-error" role="alert">{error}</p>}</Dialog>;
}

function ImportWizard({ kind, onClose, onFinish, toast }) {
  const historical = kind === 'history'; const knowledge = kind === 'knowledge';
  const [step, setStep] = useState(0); const [file, setFile] = useState(null); const [fixed, setFixed] = useState(false); const [range, setRange] = useState('已定稿且本人有权访问的历史 RFQ'); const [doneCount, setDoneCount] = useState(0);
  const rows = knowledge ? [{id:'DEMO-K-101', title:'设备支持 300 mm 晶圆', answer:'Comply，适用标准上料模块 S。', conditions:'机型 A R2；标准模块 S；硅晶圆', evidence:'T-01 v2，第 8 页', source:'历史 RFQ-018 · 条款 3.2'}, {id:'DEMO-K-102', title:'厚度 0.5–1.0 mm 加工能力', answer:'Comply，需采用工艺 P1。', conditions:fixed ? '机型 A R2；硅材料；工艺 P1' : '', evidence:fixed ? 'T-01 v2，第 8 页' : '', source:'历史 RFQ-018 · 条款 2.1'}] : [{id:historical?'DEMO-CAP-H1':'DEMO-CAP-X1', metric:historical?'定位精度':'加工厚度', value:historical?'≤5 μm':'0.5–1.0 mm', conditions:'硅材料；工艺 P1；测试方法 M1', evidence:'T-01 v2，第 8 页', config:'CFG-A-R2 v1 + 模块 X', source:historical?'历史 RFQ':'Excel'}, {id:historical?'DEMO-CAP-H2':'DEMO-CAP-X2', metric:'产能', value:'120 片/小时', conditions:fixed?'硅晶圆；标准模块 S；工艺 P1':'', evidence:fixed?'T-01 v2，第 9 页':'', config:'CFG-A-R2 v1', source:historical?'历史 RFQ':'Excel'}];
  const title = knowledge ? '批量导入历史知识' : historical ? '历史 RFQ 自动抽取' : 'Excel 上传能力边界';
  return <Dialog title={title} onClose={onClose} wide footer={<><button className="btn" onClick={onClose}>{step === 2 ? '完成' : '取消'}</button>{step === 0 && <button className="btn btn-primary" onClick={() => setStep(1)}>运行演示预检</button>}{step === 1 && <button className="btn btn-primary" onClick={() => { const valid = rows.filter((r) => r.conditions && r.evidence); onFinish(valid); setDoneCount(valid.length); setStep(2); }}>将 {fixed ? 2 : 1} 条有效记录保存为候选</button>}</>}><div className="ref-steps">{['选择来源', '字段预检与候选', '保存结果'].map((s, i) => <span key={s} className={step >= i ? 'active' : ''}><b>{i + 1}</b>{s}</span>)}</div><Notice>演示模式：仅保存文件名或授权范围，不读取或解析真实文件内容。下列候选是固定演示数据，不代表实际设备能力。</Notice>{step === 0 && <><Field label={historical ? '授权历史范围' : '选择 Excel / CSV 文件（可选）'}>{historical ? <Select value={range} onChange={setRange} options={['已定稿且本人有权访问的历史 RFQ', '历史 RFQ-018 · 已定稿', '历史 RFQ-012 · 已定稿']}/> : <div className="ref-upload"><Upload size={28}/><strong>{file?.name || '选择文件，或直接使用演示样例'}</strong><input type="file" accept=".xlsx,.xls,.csv" aria-label="选择导入文件" onChange={(e) => setFile(e.target.files[0] || null)}/><small>上传仅用于交互演示；实际内容不会解析或发送。</small></div>}</Field><button className="btn" onClick={() => { csvDownload(knowledge ? '历史知识固定模板.csv' : '能力边界固定模板.csv', knowledge ? [['历史要求','最终答复','来源','审核信息','产品范围','访问范围','适用条件','证据'],['示例要求','示例答复','历史 RFQ-018','王工审核','机型 A R2','FEP 授权项目','硅材料；工艺 P1','T-01 v2']] : [['机型','配置','指标','能力值','值类型','适用条件','限制','证据','批准人'],['机型 A R2','CFG-A-R2 v1','加工厚度','0.5–1.0 mm','保证值','硅材料；工艺 P1','其他材料需重新评审','T-01 v2','王工']]); toast?.('CSV 模板已下载，可用 Excel 打开'); }}><Download size={16}/>下载固定模板（CSV）</button></>}{step === 1 && <><div className="ref-import-meta"><span>来源：{historical ? range : file?.name || '内置演示样例'}</span><Tag>{fixed ? '预检通过' : '存在缺项'}</Tag></div><div className="table-wrap"><table className="data-table"><thead><tr><th>行号</th><th>原文 / 候选内容</th><th>定位 / 来源</th><th>预检结果</th></tr></thead><tbody>{rows.map((row, i) => <tr key={row.id}><td>{i + 2}</td><td><strong>{row.title || `${row.metric} ${row.value}`}</strong><small>{row.conditions || '适用条件缺失'}</small></td><td>{row.source}<small>{row.evidence || '证据未关联'}</small></td><td>{row.conditions ? <Tag>可生成候选</Tag> : <><Tag>待补齐</Tag><small className="ref-error">缺少适用条件及有效证据</small></>}</td></tr>)}</tbody></table></div>{!fixed && <button className="btn" onClick={() => setFixed(true)}>填入演示修正值并重新预检</button>}<p className="muted">成功项仅形成草稿。重复导入相同演示编号会跳过已成功记录；缺项行可修正重试。</p></>}{step === 2 && <div className="ref-success-state"><CheckCircle2 size={48}/><h3>{doneCount} 条候选已处理</h3><p>已生成草稿，重复记录已自动跳过。核对范围和证据后，可在详情中提交审核。</p><Tag>尚未发布，不可直接引用</Tag></div>}</Dialog>;
}

