export function EvidencePage({ toast, project, actorRole = '销售负责人', navigate, logEvent }) {
  const [items,setItems] = useSaved('rfq.reference.evidence.v1',EVIDENCE); const [group,setGroup] = useState('全部资料'); const [query,setQuery] = useState(''); const [status,setStatus] = useState('全部状态'); const [purpose,setPurpose] = useState('全部用途'); const [model,setModel] = useState('全部产品'); const [refFilter,setRefFilter] = useState('全部引用'); const [selected,setSelected] = useState('T-01:2'); const [detailTab,setDetailTab] = useState('detail'); const [drawer,setDrawer] = useState(null); const [form,setForm] = useState(null); const [file,setFile] = useState(null); const [error,setError] = useState(''); const [validity,setValidity] = useState(null); const [reason,setReason] = useState(''); const [validityTarget,setValidityTarget] = useState('有效'); const [link,setLink] = useState(null);
  const notify = (message) => {toast?.(message);logEvent?.(message);};
  const [page,setPage] = useState(1); const [pageSize,setPageSize] = useState(10);
  useEffect(() => setPage(1), [query,status,group,purpose,model,refFilter]);
  const filtered = items.filter((r) => (group === '全部资料' || r.group === group) && (status === '全部状态' || r.status === status) && (purpose === '全部用途' || r.purpose === purpose) && (model === '全部产品' || r.model === model) && (refFilter === '全部引用' || (refFilter === '已被引用' ? r.refs.length > 0 : !r.refs.length)) && `${r.id}${r.name}${r.source}${r.conditions}`.toLowerCase().includes(query.toLowerCase()));
  const pageItems = filtered.slice((Math.min(page,Math.max(1,Math.ceil(filtered.length/pageSize)))-1)*pageSize,Math.min(page,Math.max(1,Math.ceil(filtered.length/pageSize)))*pageSize);
  const current = filtered.find((r) => `${r.id}:${r.version}` === selected) || filtered[0];
  const update = (item) => setItems((all) => all.map((r) => r.id === item.id && r.version === item.version ? item : r));
  const openUpload = (item) => {setFile(null);setError('');setForm(item ? {...item,newVersion:true,reason:''} : {id:uid('DOC'),name:'',version:1,group:'项目资料',purpose:'补充附件',model:'机型 A R2',owner:actorRole,source:'',sourceDate:today(),expiry:'2027-10-20',scope:'仅当前项目',status:'待核对',conditions:'',location:'',external:false,refs:[],history:[],reason:''});};
  const saveUpload = () => { if ((!file && !form.newVersion) || !form.name.trim() || !form.source.trim() || !form.sourceDate || !form.expiry || !form.conditions.trim()) return setError('请选择文件并填写名称、来源日期、有效期和适用条件。'); if (form.newVersion && !form.reason.trim()) return setError('更新版本必须填写原因。'); if (form.expiry < form.sourceDate) return setError('有效期不能早于来源日期。'); const item = {...form,version:form.newVersion ? Math.max(...items.filter((r) => r.id === form.id).map((r) => r.version)) + 1 : 1,status:'待核对',checkedBy:'尚未完成专业核对',fileType:file?.name.split('.').pop().toUpperCase() || form.fileType,fileSize:file ? `${Math.round(file.size / 1024) || 1} KB` : form.fileSize,seeded:false,history:[...(form.history || []),{date:today(),text:`${actorRole} ${form.newVersion ? `更新资料版本：${form.reason}` : '登记文件元数据（演示）'}；待专业核对`}]}; delete item.newVersion; delete item.reason; setItems((all) => [...all,item]);setSelected(`${item.id}:${item.version}`);setGroup('全部资料');setStatus('全部状态');setForm(null);notify('文件元数据已保存，等待专业核对；未上传或解析真实内容'); };
  const openValidity = (item, target) => {setValidity(item);setValidityTarget(target || '有效');setReason('');setError('');};
  const changeValidity = () => {if (!reason.trim()) return setError('请填写核对说明或变更原因。'); if (validityTarget === '有效' && !['技术确认人','最终审批人'].includes(actorRole)) return setError('当前角色无专业确认权限，请使用技术确认人或最终审批人演示。'); if (validityTarget === '有效' && validity.expiry < today()) return setError('资料已过有效期，请先更新版本。'); const item = {...validity,status:validityTarget,checkedBy:validityTarget === '有效' ? `${actorRole} · ${today()}` : validity.checkedBy,refs:validity.refs.map((r) => ({...r,needsReview:validityTarget !== '有效'})),history:[...validity.history,{date:today(),text:`${actorRole} 变更为${validityTarget}：${reason}${validity.refs.length ? `；${validity.refs.length} 个引用待复核` : ''}`}]}; update(item);setValidity(null);notify(`资料已标记为${validityTarget}${item.refs.length ? '，相关引用已记录复核影响' : ''}`);};
  const preview = (item) => <><Notice>{item.seeded ? '演示预览：以下是基于样例元数据绘制的报告页，不代表真实文件内容。' : '此演示仅保留文件元数据，刷新后也不会恢复原件内容。请在接入存储服务后查看实际文件。'}</Notice>{item.seeded ? <div className="ref-document-preview"><div className="ref-document-brand">FEP <span>TECHNICAL DOCUMENT</span></div><h3>{item.name.replace(/\.[^.]+$/,'')}</h3><div className="ref-document-subtitle">{item.location} · {item.id} v{item.version}</div><hr/><h4>适用范围与测试条件</h4><p>{item.conditions}</p><table><thead><tr><th>核对项</th><th>记录内容（演示）</th></tr></thead><tbody><tr><td>机型 / 配置</td><td>{item.model} / CFG-A-R2 v1</td></tr><tr><td>文件来源</td><td>{item.source}</td></tr><tr><td>有效性</td><td>{item.status} / 至 {item.expiry}</td></tr></tbody></table><div className="ref-document-watermark">DEMO · 示例资料</div></div> : <div className="ref-file-placeholder"><FileText size={54}/><h3>{item.name}</h3><p>{item.fileType} · {item.fileSize}</p><Tag>文件元数据已登记</Tag></div>}</>;
  const detail = (item) => <><div className="ref-detail-title"><div><span className="ref-eyebrow">{item.id} / VERSION {item.version}</span><h3>{item.name}</h3></div><Tag>{item.status}</Tag></div><div className="ref-detail-switch"><button className={detailTab === 'detail' ? 'active' : ''} onClick={() => setDetailTab('detail')}>资料详情</button><button className={detailTab === 'refs' ? 'active' : ''} onClick={() => setDetailTab('refs')}>引用记录（{item.refs.length}）</button><button className={detailTab === 'history' ? 'active' : ''} onClick={() => setDetailTab('history')}>版本与记录</button></div>{detailTab === 'detail' && <><KeyValues entries={[["资料用途",item.purpose],['产品范围',item.model],['定位',item.location],['来源及日期',`${item.source} · ${item.sourceDate}`],['有效期',item.expiry],['维护人',item.owner],['可见范围',item.scope],['专业核对',item.checkedBy],['外发标记',item.external ? <Tag>拟对外附件</Tag> : <Tag>内部证据</Tag>]]}/><div className="ref-content-section"><span className="ref-label">适用条件</span><p>{item.conditions}</p></div><div className="ref-action-row"><button className="btn btn-primary btn-sm" onClick={() => setDrawer({item,view:'preview'})}><ExternalLink size={14}/>定位预览</button><button className="btn btn-sm" onClick={() => openUpload(item)}>更新版本</button>{item.status === '待核对' && <button className="btn btn-sm" onClick={() => openValidity(item,'有效')}>专业核对</button>}<button className="btn btn-sm" onClick={() => {setLink({item,reference:'REQ-021',reason:'',external:item.external});setError('');}}>关联与附件标记</button><button className="btn btn-danger btn-sm" onClick={() => openValidity(item,'已撤销')}>有效性变更</button></div></>}{detailTab === 'refs' && <><Notice>仅列出当前角色可访问的引用。有效性变化后，关联要求需在RFQ比对页重新复核。</Notice>{item.refs.length ? item.refs.map((r) => <button className="ref-reference-row" key={r.id} onClick={() => navigate?.(r.page)}><span className="ref-reference-icon"><FileText size={17}/></span><div><strong>{r.id} · {r.title}</strong><small>{r.type} {r.needsReview ? '· 待复核' : '· 引用当前资料版本'}</small></div><ArrowUpRight size={17}/></button>) : <Empty>暂无可访问引用</Empty>}</>}{detailTab === 'history' && <><h4 className="ref-section-title">保留的文件版本</h4>{items.filter((r) => r.id === item.id).sort((a,b) => b.version-a.version).map((r) => <div className="ref-version-row" key={r.version}><strong>v{r.version}</strong><Tag>{r.status}</Tag><span className="muted">{r.sourceDate}</span><button className="text-link" onClick={() => setSelected(`${r.id}:${r.version}`)}>查看</button></div>)}<h4 className="ref-section-title">维护记录</h4><div className="ref-timeline">{item.history.slice().reverse().map((h,i) => <div key={i}><span>{h.date}</span><p>{h.text}</p></div>)}</div></>}</>;
  return <div className="ref-page"><Heading eyebrow="DOCUMENTS & EVIDENCE" title="资料与证据管理" description="管理来源、条件与有效性，让每一次引用都有据可查。" actions={<button className="btn btn-primary" onClick={() => openUpload(null)}><Upload size={16}/>登记资料 / 上传演示</button>}/><div className="ref-stat-strip"><div><FileText size={19}/><span>可访问资料<strong>{items.length}</strong></span></div><div><ShieldCheck size={19}/><span>当前有效<strong>{items.filter((r) => r.status === '有效').length}</strong></span></div><div><History size={19}/><span>待专业核对<strong>{items.filter((r) => r.status === '待核对').length}</strong></span></div><div><Layers size={19}/><span>被引用资料<strong>{items.filter((r) => r.refs.length).length}</strong></span></div></div><section className="panel"><div className="tabs">{['全部资料','项目资料','共享能力资料'].map((g) => <button key={g} className={group === g ? 'active' : ''} onClick={() => setGroup(g)}>{g}</button>)}</div><div className="toolbar"><div className="ref-search"><Search size={16}/><input aria-label="搜索资料" placeholder="搜索资料名称、编号或来源…" value={query} onChange={(e) => setQuery(e.target.value)}/></div><Select label="资料用途" value={purpose} onChange={setPurpose} options={['全部用途','要求来源','补充附件','应答模板','能力依据']}/><Select label="有效状态" value={status} onChange={setStatus} options={['全部状态','有效','待核对','已撤销','已过期','已停用','被替代']}/><Select label="产品范围" value={model} onChange={setModel} options={['全部产品','机型 A R2','机型 A R1','机型 B R1']}/><Select label="引用关系" value={refFilter} onChange={setRefFilter} options={['全部引用','已被引用','未被引用']}/></div><div className="ref-evidence-layout"><div className="ref-evidence-list ref-table-list"><div className="ref-list-heading">资料清单 <span>{filtered.length} 条</span></div><div className="table-wrap"><table className="data-table"><thead><tr><th>资料名称 / 版本</th><th>用途 / 范围</th><th>状态</th><th>有效期</th></tr></thead><tbody>{pageItems.map((item) => <tr key={`${item.id}:${item.version}`} className={item.id === current?.id && item.version === current?.version ? 'ref-selected-row' : ''} onClick={() => {setSelected(`${item.id}:${item.version}`);setDetailTab('detail');}}><td><button className="text-link" onClick={() => {setSelected(`${item.id}:${item.version}`);setDetailTab('detail');}}>{item.name}</button><small>{item.id} · v{item.version} · {item.owner}</small></td><td>{item.purpose}<small>{item.model} · {item.refs.length} 个引用</small></td><td><Tag>{item.status}</Tag></td><td>{item.expiry}<small>来源 {item.sourceDate}</small></td></tr>)}</tbody></table>{!filtered.length && <Empty/>}</div><Paginator total={filtered.length} page={page} setPage={setPage} pageSize={pageSize} setPageSize={setPageSize}/></div><div className="ref-evidence-detail">{current ? detail(current) : <Empty>选择资料查看详情</Empty>}</div></div></section><div className="ref-bottom-notice"><ShieldCheck size={17}/><span>上传成功仅代表存储成功。内部证据与拟对外附件独立标记，正式外发仍需快照批准。</span></div>
  {drawer && <Dialog drawer title={`${drawer.item.id} v${drawer.item.version} · 定位预览`} onClose={() => setDrawer(null)} footer={<><button className="btn" onClick={() => {csvDownload(`${drawer.item.id}-演示文件元数据.csv`,[['编号','名称','版本','来源','定位','条件'],[drawer.item.id,drawer.item.name,drawer.item.version,drawer.item.source,drawer.item.location,drawer.item.conditions]]);toast?.('已下载演示文件元数据；不包含真实原件');}}><Download size={15}/>下载演示元数据</button><button className="btn btn-primary" onClick={() => setDrawer(null)}>返回资料</button></>}>{preview(drawer.item)}</Dialog>}
  {form && <Dialog title={form.newVersion ? `更新资料版本 · ${form.id}` : '登记新资料'} onClose={() => setForm(null)} wide footer={<><button className="btn" onClick={() => setForm(null)}>取消</button><button className="btn btn-primary" onClick={saveUpload}>保存资料元数据</button></>}><Notice>本原型仅登记文件元数据。选择文件不会上传、存储或解析文件内容；专业核对后才能标记为有效证据。</Notice><Field label="文件" required={!form.newVersion}><div className="ref-upload ref-upload-compact"><Upload size={23}/><strong>{file?.name || '选择本地文件（仅登记元数据）'}</strong><input type="file" aria-label="选择资料文件" onChange={(e) => {const picked = e.target.files[0];setFile(picked || null);if (picked) setForm({...form,name:picked.name});}}/></div></Field><div className="form-grid"><Field label="资料名称" required><Input value={form.name} onChange={(v) => setForm({...form,name:v})}/></Field><Field label="资料归属"><Select value={form.group} onChange={(v) => setForm({...form,group:v})} options={['项目资料','共享能力资料']}/></Field><Field label="用途"><Select value={form.purpose} onChange={(v) => setForm({...form,purpose:v})} options={['要求来源','补充附件','应答模板','能力依据']}/></Field><Field label="产品范围"><Select value={form.model} onChange={(v) => setForm({...form,model:v})} options={['机型 A R2','机型 A R1','机型 B R1']}/></Field><Field label="来源" required><Input value={form.source} onChange={(v) => setForm({...form,source:v})}/></Field><Field label="定位"><Input value={form.location} onChange={(v) => setForm({...form,location:v})} placeholder="报告第 8 页 / 工作表 B4:F18"/></Field><Field label="来源日期" required><Input type="date" value={form.sourceDate} onChange={(v) => setForm({...form,sourceDate:v})}/></Field><Field label="有效期至" required><Input type="date" value={form.expiry} onChange={(v) => setForm({...form,expiry:v})}/></Field><Field label="可见范围"><Select value={form.scope} onChange={(v) => setForm({...form,scope:v})} options={['仅当前项目','FEP 授权项目','授权专业人员']}/></Field><Field label="适用条件" required full><Area value={form.conditions} onChange={(v) => setForm({...form,conditions:v})}/></Field>{form.newVersion && <Field label="更新 / 替换原因" required full><Area value={form.reason} onChange={(v) => setForm({...form,reason:v})}/></Field>}</div>{items.some((r) => r.name === form.name && !form.newVersion) && <Notice warning>已存在同名文件。确认是否应在已有资料中选择“更新版本”，避免重复登记。</Notice>}{error && <p className="ref-error" role="alert">{error}</p>}</Dialog>}
  {validity && <Dialog title={`${validity.status === '待核对' ? '专业核对 / ' : ''}资料有效性变更`} onClose={() => setValidity(null)} footer={<><button className="btn" onClick={() => setValidity(null)}>取消</button><button className="btn btn-primary" onClick={changeValidity}>确认变更</button></>}><KeyValues entries={[["资料",`${validity.id} v${validity.version} · ${validity.name}`],['当前状态',validity.status],['有效期',validity.expiry]]}/><Field label="变更为"><Select value={validityTarget} onChange={setValidityTarget} options={['有效','待核对','已停用','已撤销','已过期','被替代']}/></Field><Field label="核对说明 / 变更原因" required><Area value={reason} onChange={setReason} placeholder="说明来源、适用条件及有效期核对结果，或变更原因"/></Field><Notice warning={validity.refs.length > 0}>可访问的影响：{validity.refs.length ? `${validity.refs.length} 个引用将保留原资料版本，并按变更结果重新校验。` : '暂无引用。'} 已引用资料不会物理删除。</Notice>{validity.refs.map((r) => <div key={r.id} className="ref-impact-row"><FileText size={15}/>{r.id} · {r.title}</div>)}{error && <p className="ref-error" role="alert">{error}</p>}</Dialog>}
  {link && <Dialog title="关联引用与外发标记" onClose={() => setLink(null)} footer={<><button className="btn" onClick={() => setLink(null)}>取消</button><button className="btn btn-primary" onClick={() => {if (!link.reason.trim()) return setError('请填写关联或标记原因。'); const exists = link.item.refs.some((r) => r.id === link.reference); const item = {...link.item,external:link.external,refs:exists ? link.item.refs : [...link.item.refs,{id:link.reference,title:`${project?.name || 'RFQ-001'} · 当前项目要求`,type:'要求',page:'response',needsReview:link.item.status !== '有效'}],history:[...link.item.history,{date:today(),text:`${actorRole} 关联 ${link.reference}；${link.external ? '标记拟对外附件' : '内部证据'}：${link.reason}`}]};update(item);setLink(null);notify('引用及附件标记已保存；正式外发仍需快照批准');}}>保存关联</button></>}><Field label="关联当前要求"><Select value={link.reference} onChange={(v) => setLink({...link,reference:v})} options={['REQ-021','REQ-022','REQ-023']}/></Field><label className="ref-checkbox"><input type="checkbox" checked={link.external} onChange={(e) => setLink({...link,external:e.target.checked})}/>标记为拟对外附件</label><Field label="关联 / 标记原因" required><Area value={link.reason} onChange={(v) => setLink({...link,reason:v})}/></Field><Notice warning={link.item.status !== '有效'}>{link.item.status !== '有效' ? '资料当前无效或尚未核对，关联不会使其成为有效证据。' : '标记拟对外附件后，仍须在导出页通过附件分标检查及快照批准。'}</Notice>{error && <p className="ref-error" role="alert">{error}</p>}</Dialog>}
  </div>;
}

